"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[305],{49352:e=>{e.exports=JSON.parse('{"functions":[{"name":"Register","desc":"Register a force-save callback. Call once per persistence manager.","params":[{"name":"flush","desc":"","lua_type":"() -> ()"}],"returns":[],"function_type":"static","source":{"line":26,"path":"src/ServerStorage/SharedModules/PersistenceRegistry.luau"}},{"name":"FlushAll","desc":"Run every registered flush in parallel and wait for all to finish or until\\n`timeoutSeconds` elapses. Returns true if all finished in time.","params":[{"name":"timeoutSeconds","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":35,"path":"src/ServerStorage/SharedModules/PersistenceRegistry.luau"}}],"properties":[],"types":[],"name":"PersistenceRegistry","desc":"Central point for force-saving every persisted player profile before the\\nserver drains players (see DisruptionCoordinator). Each persistence manager\\n(CoinManager, PerkManager, ArmorManager, SettingsManager, XPManager) calls\\n`Register` once from its `Initialize()` with a callback that iterates its\\nown active profiles and calls `profile:Save()`.\\n\\n`Save()` \u2014 not `EndSession()` \u2014 is used so players stay connected until the\\nteleport; `EndSession` (which some managers wire to a kick) still runs\\nnaturally on PlayerRemoving. ProfileStore session-locking is the correctness\\nbackstop even if a save is still in flight when a player reaches the lobby.","realm":["Server"],"source":{"line":17,"path":"src/ServerStorage/SharedModules/PersistenceRegistry.luau"}}')}}]);